@libentry()
@libtuner(configs=TRIPLET_MARGIN_LOSS_CONFIGS, key=["D"])
@triton.jit
def triplet_margin_loss_inf_kernel(
    anchor_ptr,
    positive_ptr,
    negative_ptr,
    out_ptr,
    N,
    D,
    eps,
    margin,
    SWAP: tl.constexpr,
    IS_MAX: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_D: tl.constexpr,
):
    # p = +inf -> max coordinate distance; p = -inf -> min coordinate distance.
    acc_dtype = (
        tl.float64 if anchor_ptr.type.element_ty == tl.float64 else tl.float32
    )  # noqa: E501
    pid = tl.program_id(0) * BLOCK_M + tl.arange(0, BLOCK_M)[:, None]
    row_mask = pid < N

    if IS_MAX:
        # abs values are >= 0, so 0 is a safe lower bound for masked lanes.
        init = 0.0
    else:
        init = float("inf")
    acc_ap = tl.full([BLOCK_M], init, dtype=acc_dtype)
    acc_an = tl.full([BLOCK_M], init, dtype=acc_dtype)
    acc_pn = tl.full([BLOCK_M], init, dtype=acc_dtype)

    for start in range(0, D, BLOCK_D):
        cols = start + tl.arange(0, BLOCK_D)[None, :]
        col_mask = cols < D
        mask = row_mask & col_mask
        a = tl.load(anchor_ptr + pid * D + cols, mask=mask, other=0).to(
            acc_dtype
        )  # noqa: E501
        pos = tl.load(positive_ptr + pid * D + cols, mask=mask, other=0).to(
            acc_dtype
        )  # noqa: E501
        neg = tl.load(negative_ptr + pid * D + cols, mask=mask, other=0).to(
            acc_dtype
        )  # noqa: E501

        diff_ap = tl.abs(a - pos + eps)
        diff_an = tl.abs(a - neg + eps)
        if IS_MAX:
            acc_ap = tl.maximum(
                acc_ap, tl.max(tl.where(mask, diff_ap, init), axis=1)
            )  # noqa: E501
            acc_an = tl.maximum(
                acc_an, tl.max(tl.where(mask, diff_an, init), axis=1)
            )  # noqa: E501
        else:
            acc_ap = tl.minimum(
                acc_ap, tl.min(tl.where(mask, diff_ap, init), axis=1)
            )  # noqa: E501
            acc_an = tl.minimum(
                acc_an, tl.min(tl.where(mask, diff_an, init), axis=1)
            )  # noqa: E501
        if SWAP:
            diff_pn = tl.abs(pos - neg + eps)
            if IS_MAX:
                acc_pn = tl.maximum(
                    acc_pn, tl.max(tl.where(mask, diff_pn, init), axis=1)
                )  # noqa: E501
            else:
                acc_pn = tl.minimum(
                    acc_pn, tl.min(tl.where(mask, diff_pn, init), axis=1)
                )  # noqa: E501

    dist_ap = acc_ap
    dist_an = acc_an
    if SWAP:
        dist_pn = acc_pn
        dist_an = tl.minimum(dist_an, dist_pn)

    loss = dist_ap - dist_an + margin
    loss = tl.maximum(loss, 0.0)
    tl.store(out_ptr + pid, loss[:, None], row_mask)


# ---------------------------------------------------------------------------
# Split reduction over the feature dimension
#
# Every kernel above walks the whole feature dimension D inside one program, so
# the grid is cdiv(N, BLOCK_M) and D only makes each program longer.  A 1-D
# input (N = 1) therefore runs a *single* program: 2^20 features took 20 ms,
# and the 2^30-feature benchmark case ran for tens of seconds per call, which
# the harness kills.  When the row grid leaves the device idle, the feature
# dimension is cut into ``n_split`` contiguous segments of ``seg = D / n_split``
# elements.  ``[N, n_split, seg]`` is still contiguous, so stage one reuses the
# row kernels' arithmetic with ``N * n_split`` rows of length ``seg`` and only
# has to write the raw accumulators; stage two folds the segments of each row
# back together and applies the p-th root, the swap minimum and the margin.
# ---------------------------------------------------------------------------
# Feature dimension below which the extra launch cannot pay off.
_SPLIT_MIN_D = 65536
# Rows every program must have before the row grid alone keeps the device busy
# (48 compute units, and the smallest autotuned BLOCK_M is 8).
_SPLIT_MAX_ROWS = 48
# Elements per segment: one serial walk of the chunk kernel.  Measured optimum
# on gcu400 is the same element count as the plain kernels' tile budget.
_SEG_TARGET = 16384
# Rows and segments per program in the merge stage.  The merge only touches
# K partials per row, so this is a pure throughput tile.
_MERGE_BLOCK_N = 128
_MERGE_BLOCK_K = 128
# gcu400 rejects grid.x above 16 bits.  Rows per launch are sized against the
# narrowest row block of the autotune set (BLOCK_M = 8) so that any selected
# configuration stays inside the limit.
_MAX_ROWS_PER_LAUNCH = 65535 * 8

# p variants understood by both split stages.  Declared as constexpr because
# the kernels branch on them at trace time.
_P_ABS = tl.constexpr(0)  # p = 1
_P_SQUARE = tl.constexpr(1)  # p = 2
_P_COUNT = tl.constexpr(2)  # p = 0
_P_GENERAL = tl.constexpr(3)  # any other finite p
_P_MAX = tl.constexpr(4)  # p = +inf
_P_MIN = tl.constexpr(5)  # p = -inf


@libentry()
@libtuner(configs=TRIPLET_MARGIN_LOSS_CONFIGS, key=["D"])
@triton.jit
def triplet_margin_loss_partial_kernel(
    anchor_ptr,
    positive_ptr,
    negative_ptr,
    part_ap_ptr,
    part_an_ptr,
    part_pn_ptr,
    N,
    D,
    eps,
    p,
    SWAP: tl.constexpr,
    P_KIND: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_D: tl.constexpr,
):
    """Stage one: reduce one contiguous segment of a row to a scalar."""
    acc_dtype = (
        tl.float64 if anchor_ptr.type.element_ty == tl.float64 else tl.float32
    )  # noqa: E501
    pid = tl.program_id(0) * BLOCK_M + tl.arange(0, BLOCK_M)[:, None]
    row_mask = pid < N

    if P_KIND == _P_MAX:
        # abs values are >= 0, so 0 is a safe lower bound for masked lanes.
        init = 0.0
    elif P_KIND == _P_MIN:
        init = float("inf")
    else:
        init = 0.0
    acc_ap = tl.full([BLOCK_M], init, dtype=acc_dtype)
    acc_an = tl.full([BLOCK_M], init, dtype=acc_dtype)
    acc_pn = tl.full([BLOCK_M], init, dtype=acc_dtype)

    if P_KIND == _P_GENERAL:
        p = p.to(acc_dtype)

    for start in range(0, D, BLOCK_D):
        cols = start + tl.arange(0, BLOCK_D)[None, :]
        mask = row_mask & (cols < D)
        a = tl.load(anchor_ptr + pid * D + cols, mask=mask, other=0).to(
            acc_dtype
        )  # noqa: E501
        pos = tl.load(positive_ptr + pid * D + cols, mask=mask, other=0).to(
            acc_dtype
        )  # noqa: E501
        neg = tl.load(negative_ptr + pid * D + cols, mask=mask, other=0).to(
            acc_dtype
        )  # noqa: E501

        shifted_ap = a - pos + eps
        shifted_an = a - neg + eps
        diff_ap = tl.abs(shifted_ap)
        diff_an = tl.abs(shifted_an)

        if P_KIND == _P_SQUARE:
            acc_ap += tl.sum(tl.where(mask, diff_ap * diff_ap, 0.0), axis=1)
            acc_an += tl.sum(tl.where(mask, diff_an * diff_an, 0.0), axis=1)
        elif P_KIND == _P_COUNT:
            acc_ap += tl.sum(tl.where(mask & (shifted_ap != 0.0), 1.0, 0.0), axis=1)
            acc_an += tl.sum(tl.where(mask & (shifted_an != 0.0), 1.0, 0.0), axis=1)
        elif P_KIND == _P_GENERAL:
            acc_ap += tl.sum(tl.where(mask, exp2(p * log2(diff_ap)), 0.0), axis=1)
            acc_an += tl.sum(tl.where(mask, exp2(p * log2(diff_an)), 0.0), axis=1)
        elif P_KIND == _P_MAX:
            acc_ap = tl.maximum(acc_ap, tl.max(tl.where(mask, diff_ap, init), axis=1))
            acc_an = tl.maximum(acc_an, tl.max(tl.where(mask, diff_an, init), axis=1))
        elif P_KIND == _P_MIN:
            acc_ap = tl.minimum(acc_ap, tl.min(tl.where(mask, diff_ap, init), axis=1))
            acc_an = tl.minimum(acc_an, tl.min(tl.where(mask, diff_an, init), axis=1))
        else:  # _P_ABS
            acc_ap += tl.sum(tl.where(mask, diff_ap, 0.0), axis=1)
            acc_an += tl.sum(tl.where(mask, diff_an, 0.0), axis=1)

        if SWAP:
            shifted_pn = pos - neg + eps
            diff_pn = tl.abs(shifted_pn)
            if P_KIND == _P_SQUARE:
                acc_pn += tl.sum(tl.where(mask, diff_pn * diff_pn, 0.0), axis=1)
            elif P_KIND == _P_COUNT:
                acc_pn += tl.sum(
                    tl.where(mask & (shifted_pn != 0.0), 1.0, 0.0), axis=1
                )  # noqa: E501
            elif P_KIND == _P_GENERAL:
                acc_pn += tl.sum(
                    tl.where(mask, exp2(p * log2(diff_pn)), 0.0), axis=1
                )  # noqa: E501
            elif P_KIND == _P_MAX:
                acc_pn = tl.maximum(
                    acc_pn, tl.max(tl.where(mask, diff_pn, init), axis=1)
                )  # noqa: E501
            elif P_KIND == _P_MIN:
                acc_pn = tl.minimum(
                    acc_pn, tl.min(tl.where(mask, diff_pn, init), axis=1)
                )  # noqa: E501
            else:  # _P_ABS
                acc_pn += tl.sum(tl.where(mask, diff_pn, 0.0), axis=1)

    tl.store(part_ap_ptr + pid, acc_ap[:, None], row_mask)
    tl.store(part_an_ptr + pid, acc_an[:, None], row_mask)
    if SWAP:
        tl.store(part_pn_ptr + pid, acc_pn[:, None], row_mask)


@libentry()
@triton.jit
def triplet_margin_loss_split_merge_kernel(
    part_ap_ptr,
    part_an_ptr,
    part_pn_ptr,
    out_ptr,
    N,
    K,
    margin,
    p,
    SWAP: tl.constexpr,
    P_KIND: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
):
    """Stage two: fold the ``K`` segment partials of every row back together."""
    acc_dtype = (
        tl.float64 if part_ap_ptr.type.element_ty == tl.float64 else tl.float32
    )  # noqa: E501
    n_offs = tl.program_id(0) * BLOCK_N + tl.arange(0, BLOCK_N)
    mask_n = n_offs < N

    if P_KIND == _P_MAX:
        init = 0.0
    elif P_KIND == _P_MIN:
        init = float("inf")
    else:
        init = 0.0
    acc_ap = tl.full([BLOCK_N], init, dtype=acc_dtype)
    acc_an = tl.full([BLOCK_N], init, dtype=acc_dtype)
    acc_pn = tl.full([BLOCK_N], init, dtype=acc_dtype)

    for k_start in range(0, K, BLOCK_K):
        k_offs = k_start + tl.arange(0, BLOCK_K)
        mask = (k_offs[:, None] < K) & mask_n[None, :]
        # Partials are laid out [row, segment], so the segments of one row are
        # contiguous and the load is coalesced along the segment axis.
        offsets = n_offs[None, :] * K + k_offs[:, None]
        v_ap = tl.load(part_ap_ptr + offsets, mask=mask, other=init)
        v_an = tl.load(part_an_ptr + offsets, mask=mask, other=init)
        if P_KIND == _P_MAX:
            acc_ap = tl.maximum(acc_ap, tl.max(v_ap, axis=0))
            acc_an = tl.maximum(acc_an, tl.max(v_an, axis=0))
        elif P_KIND == _P_MIN:
            acc_ap = tl.minimum(acc_ap, tl.min(v_ap, axis=0))
            acc_an = tl.minimum(acc_an, tl.min(v_an, axis=0))
        else:
            acc_ap += tl.sum(v_ap, axis=0)
            acc_an += tl.sum(v_an, axis=0)

        if SWAP:
            v_pn = tl.load(part_pn_ptr + offsets, mask=mask, other=init)
            if P_KIND == _P_MAX:
                acc_pn = tl.maximum(acc_pn, tl.max(v_pn, axis=0))
            elif P_KIND == _P_MIN:
                acc_pn = tl.minimum(acc_pn, tl.min(v_pn, axis=0))
            else:
                acc_pn += tl.sum(v_pn, axis=0)

    if P_KIND == _P_SQUARE:
        dist_ap = tl.sqrt(acc_ap)
        dist_an = tl.sqrt(acc_an)
    elif P_KIND == _P_GENERAL:
        inv_p = 1.0 / p.to(acc_dtype)
        dist_ap = exp2(inv_p * log2(acc_ap))
        dist_an = exp2(inv_p * log2(acc_an))
    else:
        dist_ap = acc_ap
        dist_an = acc_an

    if SWAP:
        if P_KIND == _P_SQUARE:
            dist_pn = tl.sqrt(acc_pn)
        elif P_KIND == _P_GENERAL:
            inv_p = 1.0 / p.to(acc_dtype)
            dist_pn = exp2(inv_p * log2(acc_pn))
        else:
            dist_pn = acc_pn
        dist_an = tl.minimum(dist_an, dist_pn)

    loss = dist_ap - dist_an + margin
    loss = tl.maximum(loss, 0.0)
    tl.store(out_ptr + n_offs, loss, mask_n)


def _row_groups(rows):
    """Row ranges that keep the launched ``grid.x`` inside the hardware limit.

    ``_MAX_ROWS_PER_LAUNCH`` is sized with the narrowest row block of the
    autotuned set, so every configuration fits once the row count is split at
    these boundaries.
    """
    if rows <= _MAX_ROWS_PER_LAUNCH:
        yield 0, rows
        return
    for row_lo in range(0, rows, _MAX_ROWS_PER_LAUNCH):
        yield row_lo, min(row_lo + _MAX_ROWS_PER_LAUNCH, rows)


def _dispatch_plain(p, anchor, positive, negative, out, rows, D, eps, margin, swap):
    """Launch the per-row p variant over ``rows`` rows of length ``D``."""
    grid = lambda meta: (triton.cdiv(rows, meta["BLOCK_M"]),)  # noqa: E731
    if p == 1.0:
        triplet_margin_loss_p1_kernel[grid](
            anchor, positive, negative, out, rows, D, eps, margin, SWAP=swap
        )
    elif p == 2.0:
        triplet_margin_loss_p2_kernel[grid](
            anchor, positive, negative, out, rows, D, eps, margin, SWAP=swap
        )
    elif p == 0.0:
        triplet_margin_loss_p0_kernel[grid](
            anchor, positive, negative, out, rows, D, eps, margin, SWAP=swap
        )
    elif p == float("inf"):
        triplet_margin_loss_inf_kernel[grid](
            anchor,
            positive,
            negative,
            out,
            rows,
            D,
            eps,
            margin,
            SWAP=swap,
            IS_MAX=True,
        )
    elif p == float("-inf"):
        triplet_margin_loss_inf_kernel[grid](
            anchor,
            positive,
            negative,
            out,
            rows,
            D,
            eps,
            margin,
            SWAP=swap,
            IS_MAX=False,
        )
    else:
        triplet_margin_loss_general_kernel[grid](
            anchor, positive, negative, out, rows, D, eps, p, margin, SWAP=swap
        )


def _split_count(D):
    """Segments per row for the split reduction, or 1 to keep the plain path.

    The segment count has to divide ``D`` so that ``[N * n_split, seg]`` stays a
    valid view of the contiguous input, hence the power-of-two clamp to the
    largest divisor of ``D`` (an odd ``D`` therefore stays unsplit).
    """
    if D < _SPLIT_MIN_D:
        return 1
    wanted = triton.cdiv(D, _SEG_TARGET)
    divisor = D & -D
    count = min(wanted, divisor)
    return 1 << (count.bit_length() - 1)


def triplet_margin_loss(
    anchor,
    positive,
    negative,
    margin=1.0,
    p=2.0,
    eps=1e-6,
    swap=False,
    reduction="mean",
):
    logger.debug("GEMS_ENFLAME TRIPLET_MARGIN_LOSS")

    # reduction may come as an aten integer (0=none, 1=mean, 2=sum) or a string
    if isinstance(reduction, int):
        reduction = ["none", "mean", "sum"][reduction]

    # Match ATen's input contract: same-rank broadcastable shapes are valid and
    # mixed input dtypes follow normal type promotion. Broadcast first, then
    # promote every operand to the common dtype so the kernel sees one dtype and
    # the output uses the promoted dtype.
    out_dtype = torch.promote_types(
        torch.promote_types(anchor.dtype, positive.dtype), negative.dtype
    )
    anchor, positive, negative = torch.broadcast_tensors(anchor, positive, negative)

    # Enflame GCU400 lowering: the Triton compiler cannot lower fp64 kernels
    # (compilation segfaults in make_gcuir) and the device reports
    # support_fp64 == False, while fp64 tensors themselves allocate and copy
    # fine. ATen's own fp64 path on this device also computes in fp32 (device
    # randn warns "GCU not support Double use Float replace"), so compute in
    # fp32 and widen the final result to the promoted dtype: identical
    # numerics to the native reference, with a genuine fp64 output.
    compute_dtype = out_dtype
    if out_dtype == torch.float64 and not runtime.device.support_fp64:
        compute_dtype = torch.float32

    anchor = anchor.to(compute_dtype).contiguous()
    positive = positive.to(compute_dtype).contiguous()
    negative = negative.to(compute_dtype).contiguous()

    out_shape = anchor.shape[:-1]
    D = anchor.shape[-1] if anchor.ndim > 0 else 1
    N = anchor.numel() // D if D > 0 else anchor.numel()

    out = torch.empty(out_shape, dtype=compute_dtype, device=anchor.device)

    if D == 0:
        # Empty feature dimension: every Lp distance is 0, so each sample's loss
        # collapses to clamp_min(margin, 0), matching ATen.
        out.fill_(max(float(margin), 0.0))
    elif N > 0:
        # Only a long feature dimension with few rows can leave the row grid
        # idle; that is exactly the case the split reduction exists for.
        n_split = 1
        if triton.cdiv(N, 8) < _SPLIT_MAX_ROWS:
            n_split = _split_count(D)

        with torch_device_fn.device(anchor.device):
            if n_split > 1:
                if p == 1.0:
                    p_kind = _P_ABS
                elif p == 2.0:
                    p_kind = _P_SQUARE
                elif p == 0.0:
                    p_kind = _P_COUNT
                elif p == float("inf"):
                    p_kind = _P_MAX
                elif p == float("-inf"):
                    p_kind = _P_MIN
                else:
                    p_kind = _P_GENERAL

                seg = D // n_split
                n_rows = N * n_split
                # Partials are raw accumulators (up to D terms), so they need a
                # wide dtype even when the output itself is fp16/bf16.
                part_dtype = (
                    torch.float64 if compute_dtype == torch.float64 else torch.float32
                )
                part = torch.empty((3, n_rows), dtype=part_dtype, device=anchor.device)
                anchor_flat = anchor.view(-1)
                positive_flat = positive.view(-1)
                negative_flat = negative.view(-1)
                for row_lo, row_hi in _row_groups(n_rows):
                    group_rows = row_hi - row_lo
                    split_grid = lambda meta, r=group_rows: (  # noqa: E731
                        triton.cdiv(r, meta["BLOCK_M"]),
                    )
                    triplet_margin_loss_partial_kernel[split_grid](
                        anchor_flat[row_lo * seg :],
                        positive_flat[row_lo * seg :],
                        negative_flat[row_lo * seg :],
                        part[0, row_lo:],
                        part[1, row_lo:],
                        part[2, row_lo:],
                        group_rows,
                        seg,
                        eps,
                        p,
                        SWAP=swap,
                        P_KIND=p_kind,
                    )
                triplet_margin_loss_split_merge_kernel[
                    (triton.cdiv(N, _MERGE_BLOCK_N),)
                ](
                    part[0],
                    part[1],
                    part[2],
                    out,
                    N,
                    n_split,
                    margin,
                    p,
                    SWAP=swap,
                    P_KIND=p_kind,
                    BLOCK_N=_MERGE_BLOCK_N,
                    BLOCK_K=_MERGE_BLOCK_K,
                )
            elif N > _MAX_ROWS_PER_LAUNCH:
                # gcu400 rejects grid.x > 65535, so a row count that large is
                # spread over several launches of the same kernel.
                anchor_flat = anchor.view(-1)
                positive_flat = positive.view(-1)
                negative_flat = negative.view(-1)
                out_flat = out.view(-1)
                for row_lo, row_hi in _row_groups(N):
                    _dispatch_plain(
                        p,
                        anchor_flat[row_lo * D :],
                        positive_flat[row_lo * D :],
                        negative_flat[row_lo * D :],
                        out_flat[row_lo:],
                        row_hi - row_lo,
                        D,
                        eps,
                        margin,
                        swap,
                    )
            else:
                _dispatch_plain(
                    p, anchor, positive, negative, out, N, D, eps, margin, swap
                )

    # Reductions are routed through FlagGems' own reduction operators rather
    # than native host-side Tensor.mean()/.sum(), per the host-function
    # convention.
    if reduction == "mean":
        result = gems_mean(out)
    elif reduction == "sum":
        result = gems_sum(out)
    else:
        result = out

    # Widen back to the promoted dtype after the fp32-compute fallback so the
    # caller still observes ATen's type-promotion contract.
    if compute_dtype != out_dtype:
        result = result.to(out_dtype)
    return result
